// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(
    Object.entries(q ?? {})
      .filter(([, v]) => v !== undefined && v !== null)
      .map(([k, v]) => [k, String(v)]),
  ).toString();
  return s ? `${path}?${s}` : path;
};

/** What a kiosk screen needs to know about its own station (never the key or other stations). */
export interface StationProfileOut {
  station_id: string;
  label: string;
  device_type: "RFIDReader" | "BarcodeScanner" | "BiometricTerminal";
  location_type: "Bed" | "Ward" | "Gate" | "OT" | "Pharmacy" | "Lab" | "StaffEntrance";
  action_type: "AttendancePunch" | "BedCleaned" | "SecurityPass" | "Generic";
  ward: StationWardOut | null;
  bed_id: number | null;
  /** Scan the bed's QR sticker together with the badge */
  needs_bed_code: boolean;
  debounce_seconds: number;
  /** Ward cleaning stations: beds waiting to be cleaned */
  dirty_beds: DirtyBedOut[];
}

export interface StationWardOut {
  ward_id: number;
  name: string;
}

export interface DirtyBedOut {
  bed_id: number;
  label: string;
  current_state: "Available" | "Reserved" | "Occupied" | "Dirty" | "Cleaning" | "OutOfService";
}

export interface ScanIn {
  station_id: string;
  badge_code: string;
  /** Station clock (UTC), for scans a gateway buffered while offline; server time is used if missing, ahead of the server or older than 10 minutes */
  scanned_at?: string | null;
  /** Unique per station; makes retries idempotent */
  gateway_event_id?: string | null;
  /** Ward-level bed-cleaning stations only: the code on the bed's QR sticker */
  bed_code?: string | null;
}

export interface BadgeScanResultOut {
  scan_id: number;
  outcome: "AttendanceIn" | "AttendanceOut" | "BedCleaned" | "BedCleaningRecorded" | "SecurityPass" | "Duplicate" | "UnknownBadge" | "InactiveBadge" | "UnknownStation" | "NoAction" | "Rejected";
  /** Why a scan was rejected or did nothing */
  detail: string | null;
}

/** Kiosk screen setup: what this station does (station-authenticated) — GET /api/v1/badge-stations/me (who may call: badge station key: a badge station, by its key (X-Station-Key): no user login). */
export function meBadgeStations(query: { station_id: string }): Promise<StationProfileOut> {
  return api<StationProfileOut>("GET", withQuery(`/badge-stations/me`, query), undefined);
}

/** A badge was presented at a station (station-authenticated, no user login) — POST /api/v1/badge-stations/scans (who may call: badge station key: a badge station, by its key (X-Station-Key): no user login). */
export function scanBadgeStationsScans(body: ScanIn): Promise<BadgeScanResultOut> {
  return api<BadgeScanResultOut>("POST", `/badge-stations/scans`, body);
}
